// Package inventory 判定低库存。这是一个评测 fixture，不是生产代码。
package inventory

import (
	"encoding/json"
	"os"
	"path/filepath"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 5

// thresholdsPath 是阈值配置文件相对模块根的路径。做成变量是为了让测试指向临时文件。
var thresholdsPath = filepath.Join("config", "thresholds.json")

// moduleRoot 从当前工作目录向上找第一个含 go.mod 的目录，让 `go test`（工作目录是包目录）
// 也能读到仓库根的配置；找不到就返回 "."。
func moduleRoot() string {
	dir, err := os.Getwd()
	if err != nil {
		return "."
	}
	for {
		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
			return dir
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "."
		}
		dir = parent
	}
}

// loadThresholds 读取阈值配置。文件不存在、读不出来、内容不是 JSON 对象时返回 ok=false。
func loadThresholds() (map[string]int, bool) {
	path := thresholdsPath
	if !filepath.IsAbs(path) {
		path = filepath.Join(moduleRoot(), path)
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, false
	}
	var thresholds map[string]int
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return nil, false
	}
	return thresholds, true
}

// LowStockThreshold 返回这个仓库的低库存阈值：在 config/thresholds.json 里配了就用配置值，
// 否则（没配、文件不存在、读不出来、内容不是 JSON 对象）回退 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	thresholds, ok := loadThresholds()
	if !ok {
		return DefaultLowStockThreshold
	}
	if threshold, ok := thresholds[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}
```

