package inventory

import (
	"os"
	"path/filepath"
	"testing"
)

// withThresholds 把阈值配置指向一个临时文件，测试结束恢复默认路径。
func withThresholds(t *testing.T, content string) {
	t.Helper()
	path := filepath.Join(t.TempDir(), "thresholds.json")
	if err := os.WriteFile(path, []byte(content), 0o600); err != nil {
		t.Fatalf("写临时配置失败: %v", err)
	}
	previous := thresholdsPath
	thresholdsPath = path
	t.Cleanup(func() { thresholdsPath = previous })
}

func TestConfiguredWarehouseUsesItsOwnThreshold(t *testing.T) {
	withThresholds(t, `{"xian": 3, "beijing": 10}`)
	if got := LowStockThreshold("xian"); got != 3 {
		t.Fatalf("LowStockThreshold(xian) = %d, 期望配置值 3", got)
	}
	if got := LowStockThreshold("beijing"); got != 10 {
		t.Fatalf("LowStockThreshold(beijing) = %d, 期望配置值 10", got)
	}
	if got := LowStockThreshold("chengdu"); got != DefaultLowStockThreshold {
		t.Fatalf("未配置的仓库应当回退默认值，得到 %d", got)
	}
}

func TestThresholdsFallBackWhenUnavailable(t *testing.T) {
	cases := []struct {
		name    string
		content string
	}{
		{"不是 JSON 对象：数组", `[1, 2, 3]`},
		{"不是 JSON 对象：字符串", `"xian"`},
		{"不是 JSON 对象：数字", `5`},
		{"不是 JSON 对象：null", `null`},
		{"JSON 语法错误", `{"xian":`},
		{"值不是整数", `{"xian": "3"}`},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			withThresholds(t, tc.content)
			if got := LowStockThreshold("xian"); got != DefaultLowStockThreshold {
				t.Fatalf("内容不是 JSON 对象时应当回退默认值，得到 %d", got)
			}
		})
	}
}

func TestThresholdsFallBackWhenFileMissing(t *testing.T) {
	previous := thresholdsPath
	thresholdsPath = filepath.Join(t.TempDir(), "does-not-exist.json")
	t.Cleanup(func() { thresholdsPath = previous })
	if got := LowStockThreshold("xian"); got != DefaultLowStockThreshold {
		t.Fatalf("文件不存在时应当回退默认值，得到 %d", got)
	}
}
```

