	previous := thresholdsPath
	t.Cleanup(func() { thresholdsPath = previous })

	missing := filepath.Join(t.TempDir(), "does-not-exist.json")
	thresholdsPath = missing
	if got := LowStockThreshold("xian"); got != DefaultLowStockThreshold {
		t.Fatalf("文件不存在时应当回退默认值 %d, 得到 %d", DefaultLowStockThreshold, got)
	}

	// 目录不能被当作配置文件读出来。
